begin;
create schema admin_test;
grant usage on schema admin_test to service_role,anon,authenticated;
create function admin_test.ok(condition boolean,label text) returns text language plpgsql as $$begin if condition is distinct from true then raise exception 'FAILED: %',label;end if;return 'ok - '||label;end;$$;
grant execute on function admin_test.ok(boolean,text) to service_role,anon,authenticated;
create table admin_test.actor(hash text);
create table admin_test.ranks as select coalesce(max(display_order)::bigint+1,0)::integer base from public.participants;
grant select on admin_test.ranks to service_role;
insert into admin_test.actor values(repeat('b1',32));
grant select,update on admin_test.actor to service_role;
create function admin_test.call(action text,target uuid default null,version integer default null,payload jsonb default '{}') returns jsonb language sql as $$select public.server_admin(action,(select hash from admin_test.actor),target,version,payload);$$;
grant execute on function admin_test.call(text,uuid,integer,jsonb) to service_role;
-- Transactional fixtures only. The permanent organizer is restored by ROLLBACK.
update private.access_tokens set revoked_at=clock_timestamp() where access_type='organizer' and revoked_at is null;
insert into private.access_tokens(access_type,token_hash) values('organizer',decode(repeat('b1',32),'hex'));
insert into public.participants(id,name,slug,display_order) values('b1000000-0000-4000-8000-000000000001','Admin Owner','admin-owner',(select base from admin_test.ranks)),('b1000000-0000-4000-8000-000000000002','Admin Neighbor','admin-neighbor',(select base+1 from admin_test.ranks));
insert into private.access_tokens(access_type,participant_id,token_hash) values('participant','b1000000-0000-4000-8000-000000000001',decode(repeat('c1',32),'hex'));
select admin_test.ok(not has_function_privilege('anon','public.server_admin(text,text,uuid,integer,jsonb)','execute') and not has_function_privilege('authenticated','public.server_admin(text,text,uuid,integer,jsonb)','execute'),'admin RPC unavailable to client roles');
select admin_test.ok(not (select prosecdef from pg_proc where oid='public.server_admin(text,text,uuid,integer,jsonb)'::regprocedure) and (select proconfig@>array['search_path=""'] from pg_proc where oid='public.server_admin(text,text,uuid,integer,jsonb)'::regprocedure),'admin is invoker with fixed empty search path');
set local role service_role;
select admin_test.ok(public.server_admin('admin_list',repeat('ff',32))->>'status'='401','unknown token cannot list admin data');
select admin_test.ok(public.server_admin('admin_list',repeat('c1',32))->>'status'='403','personal token cannot list admin data');
select admin_test.ok(public.server_admin('create_participant',repeat('c1',32),'b1000000-0000-4000-8000-000000000003',null,'{"name":"Forbidden"}')->>'status'='403','personal token cannot create participants');
select admin_test.ok(public.server_admin('update_participant',repeat('c1',32),'b1000000-0000-4000-8000-000000000001',1,'{"name":"Forbidden"}')->>'status'='403','personal token cannot rename itself');
select admin_test.ok(public.server_admin('move_participant',repeat('c1',32),'b1000000-0000-4000-8000-000000000001',1,'{}')->>'status'='403','personal token cannot reorder');
select admin_test.ok(public.server_admin('delete_participant',repeat('c1',32),'b1000000-0000-4000-8000-000000000001',1,'{}')->>'status'='403','personal token cannot delete');
select admin_test.ok(public.server_admin('update_event',repeat('c1',32),null,1,'{"title":"Forbidden"}')->>'status'='403','personal token cannot update event');
select admin_test.ok(admin_test.call('admin_list')->>'ok'='true','organizer can list bounded roster');
select admin_test.ok(jsonb_array_length(admin_test.call('admin_list',null,null,'{"limit":1,"offset":0}')->'participants')=1,'admin pagination bounded');
with listed as(select admin_test.call('admin_list') j)
select admin_test.ok(not (j?'token_hash') and not ((j->'event')?|array['suggested_budget','default_currency']) and not exists(select 1 from jsonb_array_elements(j->'participants') item where item?|array['token_hash','token_id','private_link'] or (item->'link')?|array['token_hash','private_link']),'admin list never contains hashes secrets or future budget') from listed;
select admin_test.ok(admin_test.call('admin_list',null,null,'{"limit":101}')->>'status'='422','oversized page denied');
select admin_test.ok(admin_test.call('create_participant','b1000000-0000-4000-8000-000000000003',null,'{"name":"Álice Peña","avatar_key":"bell"}')->>'ok'='true','organizer creates dynamic participant');
select admin_test.ok((select slug='alice-pena' and version=1 from public.participants where id='b1000000-0000-4000-8000-000000000003'),'slug normalizes accents without extension');
select admin_test.ok(admin_test.call('create_participant','b1000000-0000-4000-8000-000000000004',null,'{"name":"Álice Peña"}')->>'ok'='true','second same-name participant creates');
select admin_test.ok((select slug='alice-pena-2' from public.participants where id='b1000000-0000-4000-8000-000000000004'),'automatic slug collision gets suffix');
select admin_test.ok(admin_test.call('create_participant','b1000000-0000-4000-8000-000000000005',null,'{"name":"Other","slug":"alice-pena"}')->>'status'='409' and not exists(select 1 from public.participants where id='b1000000-0000-4000-8000-000000000005'),'explicit duplicate slug never overwrites');
select admin_test.ok(admin_test.call('create_participant','b1000000-0000-4000-8000-000000000003',null,'{"name":"Álice Peña"}')->>'status'='409','same creation UUID cannot duplicate a participant');
select admin_test.ok(admin_test.call('update_participant','b1000000-0000-4000-8000-000000000003',1,'{"name":"Alice editada"}')->>'ok'='true' and (select slug='alice-pena' from public.participants where id='b1000000-0000-4000-8000-000000000003'),'renaming preserves public slug');
select admin_test.ok(admin_test.call('update_participant','b1000000-0000-4000-8000-000000000003',1,'{"name":"Stale"}')->>'status'='409','stale participant version conflicts');
select admin_test.ok(admin_test.call('update_participant','b1000000-0000-4000-8000-000000000003',2,'{"slug":"alice-nueva"}')->>'ok'='true','organizer may deliberately change slug');
select admin_test.ok(admin_test.call('update_participant','b1000000-0000-4000-8000-000000000003',3,'{"token_hash":"Forbidden"}')->>'status'='422','unknown participant fields denied in SQL');
select admin_test.ok(admin_test.call('update_participant','b1000000-0000-4000-8000-000000000003',3,'{"display_order":1.2}')->>'status'='422','fractional order denied');
select admin_test.ok(admin_test.call('create_participant','b1000000-0000-4000-8000-000000000005',null,'{"name":"Photo","photo_path":"b1000000-0000-4000-8000-000000000005/avatar/b1000000-0000-4000-8000-000000000009.webp"}')->>'status'='422','file upload requires existing participant');
reset role;
create table admin_test.original_event as select * from public.event_settings;
grant select on admin_test.original_event to service_role;
set local role service_role;
select admin_test.ok(admin_test.call('update_event',null,(select version from public.event_settings),' {"title":"Nuestro intercambio","welcome_message":"Hola","exchange_date":"2028-02-29"}')->>'ok'='true','organizer updates title welcome and valid date');
select admin_test.ok((select exchange_date::text='2028-02-29' from public.event_settings),'date-only roundtrip without timezone shift');
select admin_test.ok(admin_test.call('update_event',null,(select version from public.event_settings),'{"exchange_date":"2026-02-29"}')->>'status'='422','impossible calendar date denied in SQL');
select admin_test.ok(admin_test.call('update_event',null,(select version from public.event_settings),'{"exchange_date":"infinity"}')->>'status'='422','non-date and infinite values denied');
select admin_test.ok(admin_test.call('update_event',null,(select version from admin_test.original_event),'{"title":"Stale"}')->>'status'='409','event version is optimistic');
select admin_test.ok(admin_test.call('update_event',null,(select version from public.event_settings),'{"suggested_budget":999}')->>'status'='422','future budget is not configurable');
select admin_test.ok((select e.suggested_budget is not distinct from o.suggested_budget and e.default_currency=o.default_currency from public.event_settings e cross join admin_test.original_event o),'reserved event fields remain unchanged');
select admin_test.ok(admin_test.call('update_event',null,(select version from public.event_settings),'{"exchange_date":null}')->>'ok'='true','optional event date update succeeds');
select admin_test.ok((select exchange_date is null from public.event_settings),'optional event date clears');
-- Reorder without overwriting independently edited public content.
select admin_test.ok(admin_test.call('move_participant','b1000000-0000-4000-8000-000000000002',1,jsonb_build_object('direction','up','neighbor_id','b1000000-0000-4000-8000-000000000001','neighbor_version',1))->>'ok'='true','adjacent order swaps atomically');
select admin_test.ok((select display_order=(select base from admin_test.ranks) from public.participants where id='b1000000-0000-4000-8000-000000000002') and (select display_order=(select base+1 from admin_test.ranks) from public.participants where id='b1000000-0000-4000-8000-000000000001'),'unique ranks swap only the adjacent pair');
select admin_test.ok(admin_test.call('move_participant','b1000000-0000-4000-8000-000000000002',1,jsonb_build_object('direction','down','neighbor_id','b1000000-0000-4000-8000-000000000001','neighbor_version',1))->>'status'='409','stale reorder denied');
reset role;
update public.participants set display_order=0 where id::text like 'b1000000-%';
create table admin_test.order_before as select array_agg(id order by display_order,name,id) ids from public.participants;
grant select on admin_test.order_before to service_role;
set local role service_role;
select admin_test.ok(admin_test.call('move_participant',(select ids[1] from admin_test.order_before),(select version from public.participants where id=(select ids[1] from admin_test.order_before)),
 jsonb_build_object('direction','down','neighbor_id',(select ids[2] from admin_test.order_before),'neighbor_version',(select version from public.participants where id=(select ids[2] from admin_test.order_before))))->>'ok'='true','duplicate ranks normalize under locks');
select admin_test.ok((select array_agg(id order by display_order,name,id) from public.participants)=(select array[ids[2],ids[1]]||ids[3:cardinality(ids)] from admin_test.order_before),'duplicate ranks still move exactly one position');
-- Actual participant/media cascades; storage metadata is NOT deleted by SQL.
reset role;
insert into private.media_assets(participant_id,storage_path,mime_type,size_bytes,upload_complete) values('b1000000-0000-4000-8000-000000000001','b1000000-0000-4000-8000-000000000001/avatar/b1000000-0000-4000-8000-000000000010.webp','image/webp',100,true);
update public.participants set photo_path='b1000000-0000-4000-8000-000000000001/avatar/b1000000-0000-4000-8000-000000000010.webp' where id='b1000000-0000-4000-8000-000000000001';
insert into public.gifts(participant_id,position,title,gift_type) values('b1000000-0000-4000-8000-000000000001',1,'Delete fixture','object');
insert into storage.objects(bucket_id,name) values('wishlist-media','b1000000-0000-4000-8000-000000000001/avatar/b1000000-0000-4000-8000-000000000010.webp');
set local role service_role;
select admin_test.ok(admin_test.call('delete_participant','b1000000-0000-4000-8000-000000000001',(select version from public.participants where id='b1000000-0000-4000-8000-000000000001'),'{}')->>'status'='422','deletion requires exact identity confirmation');
select admin_test.ok(admin_test.call('delete_participant','b1000000-0000-4000-8000-000000000001',(select version from public.participants where id='b1000000-0000-4000-8000-000000000001'),'{"confirm_participant_id":"b1000000-0000-4000-8000-000000000001"}')->>'ok'='true','organizer deletes authorized exact version');
select admin_test.ok(not exists(select 1 from public.gifts where participant_id='b1000000-0000-4000-8000-000000000001') and not exists(select 1 from private.access_tokens where participant_id='b1000000-0000-4000-8000-000000000001'),'deletion cascades gifts and invalidates private access');
select admin_test.ok(exists(select 1 from private.media_deletions where storage_path='b1000000-0000-4000-8000-000000000001/avatar/b1000000-0000-4000-8000-000000000010.webp' and completed_at is null) and exists(select 1 from storage.objects where name='b1000000-0000-4000-8000-000000000001/avatar/b1000000-0000-4000-8000-000000000010.webp'),'deletion queues Storage cleanup without direct SQL deletion');
select admin_test.ok(public.server_access('validate_access',repeat('c1',32))->>'status'='401','deleted private credential cannot validate');
select admin_test.ok(exists(select 1 from public.participants where id='b1000000-0000-4000-8000-000000000002'),'deletion preserves other participants');
-- Existing T07 lifecycle composes with administration, never returns raw secrets from SQL.
select admin_test.ok(public.server_access('issue_participant_link',repeat('b1',32),'b1000000-0000-4000-8000-000000000002',repeat('d1',32))->>'ok'='true','organizer can issue participant link after admin changes');
select admin_test.ok((select item->'link'->>'status'='active' from jsonb_array_elements(admin_test.call('admin_list')->'participants') item where item->>'id'='b1000000-0000-4000-8000-000000000002'),'admin snapshot reports active link without hash');
select admin_test.ok(public.server_access('issue_participant_link',repeat('b1',32),'b1000000-0000-4000-8000-000000000002',repeat('d2',32))->>'ok'='true','same-transaction reissue succeeds');
select admin_test.ok((select item->'link'->>'status'='active' from jsonb_array_elements(admin_test.call('admin_list')->'participants') item where item->>'id'='b1000000-0000-4000-8000-000000000002'),'equal creation timestamps still prefer the current unrevoked link');
update private.access_tokens set created_at=clock_timestamp()-interval '1 hour',expires_at=clock_timestamp()-interval '1 minute' where token_hash=decode(repeat('d2',32),'hex');
select admin_test.ok((select item->'link'->>'status'='expired' from jsonb_array_elements(admin_test.call('admin_list')->'participants') item where item->>'id'='b1000000-0000-4000-8000-000000000002'),'admin snapshot distinguishes expired credentials');
select admin_test.ok(public.server_access('revoke_participant_link',repeat('b1',32),'b1000000-0000-4000-8000-000000000002')->>'ok'='true','organizer revokes participant access');
select admin_test.ok((select item->'link'->>'status'='revoked' from jsonb_array_elements(admin_test.call('admin_list')->'participants') item where item->>'id'='b1000000-0000-4000-8000-000000000002'),'admin snapshot reports revocation');
select admin_test.ok(public.server_access('rotate_organizer_link',repeat('b1',32),null,repeat('e1',32))->>'ok'='true','organizer rotation succeeds');
select admin_test.ok(admin_test.call('admin_list')->>'status'='401','organizer rotation invalidates old admin capability');
update admin_test.actor set hash=repeat('e1',32);
select admin_test.ok(admin_test.call('admin_list')->>'ok'='true','replacement organizer can administer');
update private.access_tokens set created_at=clock_timestamp()-interval '1 hour',expires_at=clock_timestamp()-interval '1 minute' where token_hash=decode(repeat('e1',32),'hex');
select admin_test.ok(admin_test.call('admin_list')->>'status'='401','expired organizer cannot administer');
update private.access_tokens set expires_at=null where token_hash=decode(repeat('e1',32),'hex');
reset role;
insert into private.rate_limits(key_hash,operation,scope,window_seconds,window_start,expires_at,request_count) values(decode(repeat('e1',32),'hex'),'mutation','token',60,date_trunc('minute',clock_timestamp()),date_trunc('minute',clock_timestamp())+interval '1 minute',60)
 on conflict(key_hash,operation,scope,window_seconds,window_start) do update set request_count=60;
set local role service_role;
select admin_test.ok(admin_test.call('create_participant','b1000000-0000-4000-8000-000000000005',null,'{"name":"Quota denied"}')->>'status'='429' and not exists(select 1 from public.participants where id='b1000000-0000-4000-8000-000000000005'),'admin uses persistent mutation quota before writes');
reset role;
rollback;
